set-variable.value:
@{
      var config = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("__AUTHORIZATION_BASE64__")));
      var deny = new JObject(new JProperty("allowed", false));
      var keyHeader = (string)context.Variables["gatewayKeyHeader"];
      if ((string)config["mode"] != "subscriptionKey") { return deny.ToString(); }
      JObject decision;
      if (context.Request.Headers.ContainsKey(keyHeader)) {
        /* 購読とキー用ヘッダーの形式は共通認証で確認済みです。検証済み購読IDを呼出主体へ引き継ぎます。 */
        decision = new JObject(new JProperty("allowed", true),
          new JProperty("callerId", "subscription:" + context.Subscription.Id), new JProperty("method", "subscriptionKey"));
      } else {
        try {
          if (context.Subscription != null
              || !context.Variables.ContainsKey("gatewayCommonAuthenticationValidated") || !(bool)context.Variables["gatewayCommonAuthenticationValidated"]
              || !context.Variables.ContainsKey("gatewayEntraAuthenticationValidated") || !(bool)context.Variables["gatewayEntraAuthenticationValidated"]) { return deny.ToString(); }
          var user = JObject.Parse((string)context.Variables["gatewayUserAuthentication"]);
          Guid tenant, principal;
          if ((int?)user["schemaVersion"] != 1
              || !Guid.TryParse((string)user["tenantId"], out tenant) || tenant == Guid.Empty
              || !Guid.TryParse((string)user["principalId"], out principal) || principal == Guid.Empty) { return deny.ToString(); }
          var caller = "user:" + tenant.ToString("D") + ":" + principal.ToString("D");
          if ((string)user["callerId"] != caller || (string)user["allocationId"] != caller) { return deny.ToString(); }
          decision = new JObject(new JProperty("allowed", true), new JProperty("method", "user"),
            new JProperty("callerId", caller), new JProperty("allocationId", caller),
            new JProperty("verifiedTenantId", tenant.ToString("D")), new JProperty("verifiedPrincipalId", principal.ToString("D")),
            new JProperty("verifiedClientId", (string)user["clientId"] ?? ""));
        } catch { return deny.ToString(); }
      }
      if (context.Variables.ContainsKey("gatewayOperationSelection")) {
        /* settingIdを既存監査のprofileIdへ転記します。本文のモデル選択はここでは追加しません。 */
        var settingId = (string)JObject.Parse((string)context.Variables["gatewayOperationSelection"])["settingId"];
        if (!String.IsNullOrEmpty(settingId)) { decision["profileId"] = settingId; }
      }
      return decision.ToString(Newtonsoft.Json.Formatting.None);
    }

@{
      try {
        var message = context.Request.Body.As<JObject>(preserveContent: true);
        if ((string)message?["method"] != "tools/call" || message["id"]?.Type != JTokenType.Integer) { return ""; }
        var name = (string)message["params"]?["name"];
        var config = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("__AUTHORIZATION_BASE64__")));
        var constraint = String.IsNullOrEmpty(name) ? null : config["operationConstraints"]?[name] as JObject;
        if ((string)constraint?["kind"] != "pii") { return ""; }
        var arguments = message["params"]?["arguments"] as JObject;
        var valid = arguments != null && arguments.Properties().Count() == 2
          && arguments.Properties().All(p => p.Name == "text" || p.Name == "language")
          && arguments["text"]?.Type == JTokenType.String && !String.IsNullOrWhiteSpace((string)arguments["text"])
          && arguments["language"]?.Type == JTokenType.String
          && !String.IsNullOrWhiteSpace((string)arguments["language"])
          && (((JArray)constraint["allowedLanguages"]).Count == 0 || ((JArray)constraint["allowedLanguages"]).Any(v => (string)v == (string)arguments["language"]))
          && System.Text.Encoding.UTF8.GetByteCount(arguments.ToString(Newtonsoft.Json.Formatting.None)) <= (int)constraint["maxRequestBytes"];
        if (valid) { return ""; }
        return new JObject(new JProperty("jsonrpc", "2.0"), new JProperty("id", message["id"]),
          new JProperty("error", new JObject(new JProperty("code", -32602), new JProperty("message", "Invalid tool arguments")))).ToString(Newtonsoft.Json.Formatting.None);
      } catch { return ""; }
    }
